<?php get_header(); ?><main id="primary"><?php rzz_intro('Our team',rzz_setting('team_text','Dedicated legal professionals with a personal approach to your legal needs.')); ?><section class="section light team-directory-section pattern"><div class="container"><?php $people=get_posts(['post_type'=>'team','numberposts'=>-1,'orderby'=>'menu_order','order'=>'ASC']);$roles=[];foreach($people as $person){$r=rzz_team_role($person->ID);if($r)$roles[$r]=$r;}if(count($roles)>1&&count($people)>=4): ?><div class="team-filters" aria-label="Filter by position"><button class="button active" data-filter="all" aria-pressed="true">All</button><?php foreach($roles as $r)echo '<button class="button outline" data-filter="'.esc_attr(strtolower($r)).'" aria-pressed="false">'.esc_html($r).'</button>'; ?></div><?php endif; ?><div class="team-grid"><?php if($people):foreach($people as $post):setup_postdata($post);get_template_part('template-parts/team-card');endforeach;wp_reset_postdata();else: ?><div class="empty-state"><p class="eyebrow">People. Perspective. Partnership.</p><h2>Your legal matter deserves personal attention.</h2><p>Contact RZZ LAW to connect with the right member of our team.</p><a class="button dark" href="<?php echo esc_url(rzz_link('contact')); ?>">Contact our team <?php echo rzz_arrow(); ?></a></div><?php endif; ?></div></div></section><?php get_template_part('template-parts/principles-band'); get_template_part('template-parts/contact'); ?></main><?php get_footer(); ?>